      <li><strong>Escrita do Sudoeste:</strong> O concelho possui um conjunto importante de estelas da Idade do Ferro inscritas em Escrita do Sudoeste, considerada a mais antiga escrita conhecida da Península Ibérica. O Museu da Escrita do Sudoeste, em Almodôvar, conserva e apresenta parte deste património.</li>

