      <li><strong>Produtos Tradicionais:</strong> A economia rural do concelho está associada ao montado e à produção de cortiça, bem como ao mel, queijo de cabra e aguardente de medronho. A criação de gado e a pequena agricultura também fazem parte das actividades tradicionais.</li>
